from random import choice

class DinnerParty:
    def __init__(self):
        self.figures = [
            "Benjamin Franklin",
            "Albert Einstein",
            "Marie Curie",
            "Nikola Tesla",
            "Isaac Newton",
            "Galileo Galilei",
            "Thomas Edison",
            "Leonardo da Vinci"
        ]
        self.guests = []

    def pick_guests(self):
        for i in range(5):
            guest = choice(self.figures)
            self.guests.append(guest)
            self.figures.remove(guest)

    def get_menu(self):
        return [
            {"dish": "Chicken Parmesan", "vegetable": "Broccoli"},
            {"dish": "Spaghetti Bolognese", "vegetable": "Green beans"},
            {"dish": "Risotto", "vegetable": "Asparagus"}
        ]

    def get_dessert(self):
        desserts = ["Tiramisu", "Cheesecake", "Chocolate Lava Cake"]
        return choice(desserts)

    def plan_party(self):
        self.pick_guests()
        menu = self.get_menu()
        dessert = self.get_dessert()

        print("Guests:")
        for guest in self.guests:
            print("- " + guest)

        print("\nMenu:")
        for dish in menu:
            print("- " + dish["dish"] + " with " + dish["vegetable"])

        print("\nDessert: " + dessert)

